checks<-character()
stopifnot(nrow(d)==6000,sum(d$delivery37)==796,!anyDuplicated(d$id),all(d$delivery37 %in% 0:1))
checks<-c(checks,'Participant count, event coding and unique identifiers')
for(i in unique(round(seq(1,nrow(d),length.out=60)))){
 z<-weather[weather$site==d$site_code[i],];sel<-z$date>=d$entry_date[i]-14 & z$date<d$entry_date[i]
 stopifnot(sum(sel)==14,abs(mean(z$tmax_c[sel])-d$heat14[i])<1e-8,abs(mean(z$rain_mm[sel])-d$rain14[i])<1e-8)
}
checks<-c(checks,'Independent direct daily aggregation validates all exposure windows and rainfall in 60 records')
stopifnot(all(d$exposure_end<d$entry_date),all(d$event_interval_start[d$delivery37==1]>d$exposure_end[d$delivery37==1]))
checks<-c(checks,'All exposure measurements precede follow-up and the generated delivery interval')
unitfit<-glm(update(full_formula,.~.-heat5+heat14),data=d,family=binomial(),control=glm.control(epsilon=1e-10,maxit=100))
stopifnot(abs(coef(primary)['heat5']-5*coef(unitfit)['heat14'])<1e-7)
stopifnot(abs(sqrt(sandwich::vcovHC(primary,type='HC3')['heat5','heat5'])-5*sqrt(sandwich::vcovHC(unitfit,type='HC3')['heat14','heat14']))<1e-7)
checks<-c(checks,'Independent rescaling refit verifies odds ratios and uncertainty per five degrees C')
stopifnot(max(abs(crossprod(model.matrix(primary),d$delivery37-fitted(primary))))<1e-4)
checks<-c(checks,'Primary likelihood score is numerically zero and model matrix is full rank')
stopifnot(separation_check(cbind(1,c(0,0,0,1,1,1)),c(0,0,0,1,1,1))$complete)
stopifnot(!separation_check(cbind(1,c(0,0,0,1,1,1)),c(0,1,0,1,0,1))$separation)
quasi_test<-separation_check(cbind(1,c(0,0,1)),c(0,1,1));stopifnot(quasi_test$separation,!quasi_test$complete,separation$quasi_status %in% c(0,2),separation$complete_status %in% c(0,2))
checks<-c(checks,'Linear-program separation check correctly classifies complete, quasi and overlapping examples')
arch<-file.path(root,'archive/methods-study-v1')
original_results<-list.files(file.path(arch,'results'),recursive=TRUE,full.names=FALSE)
for(f in original_results)stopifnot(unname(tools::md5sum(file.path(root,'results',f)))==unname(tools::md5sum(file.path(arch,'results',f))))
for(f in c('illustrative_cohort.csv','weather.csv'))stopifnot(unname(tools::md5sum(file.path(root,'data',f)))==unname(tools::md5sum(file.path(arch,'data',f))))
checks<-c(checks,paste('All',length(original_results),'original result files and both source data files match the frozen archive'))
jsonlite::write_json(list(status='PASS',n=6000,events=796,checks=checks,original_results_preserved=length(original_results),primary_input_md5=as.list(tools::md5sum(file.path(root,c(config$source_cohort,config$source_weather))))),file.path(output,'validation.json'),auto_unbox=TRUE,pretty=TRUE)
cat('Association validation passed:',length(checks),'checks\n')
